window.__posterData({"id": "emili-mechilli", "name": "Emili Mechilli", "folder": "Week1_Poster_Emili_Mechilli", "v": "2", "scripts": ["https://cdn.jsdelivr.net/npm/p5@2.3.4/lib/p5.js", "https://cdn.jsdelivr.net/npm/p5.sound@0.4.1/dist/p5.sound.min.js"], "links": [], "css": "html, body {\n  margin: 0;\n  padding: 0;\n}\ncanvas {\n  display: block;\n}\n", "code": "// Halloween party poster\n// Step 1 : Refactor the code without changing functionality\n// The poster looks and works the same! It's a bit shorter now from 148 to 138 and cleaner.\n// what got changed from AI:\n// 1.First gave names to the numbers instead of createCanvas(600,800); it created CANVAS_WIDTH, CANVAS_HEIGHT and GHOST_WIDTH.\n//2. I had writen fill, textSize and text over and over and the AI made one function, label(), that does all three. \n//3. It split big functions into smaller ones.For example drawParticles now only draws dots and the new one one it put updateParticle moves them and makes them bounce.Also draw text is split in drawStartText,drawArrow and drawPartyText \n//Something that was new to me was the (rave? a:b )which is the same with the if/ else just summed up in one line \n// Something else that was new to me was for.. of loops which goes through all the dots in the list instead of using i\n\n// There is also the early return in drawGho9st whichstops the function if rave is false. Lastly it changed the label() that has parameters which means that it has written the text, position,color and size at the same line which make it more clean and organised!\n\n// My thoughts on this code is that i like that that is more easy to read and its more clean organised.\n\n// Step 2\n//Is to make the dots run away from the ghost\n// I asked the AI to make the dots go away from the ghost (the mouse) in party mode.When the ghost is close the dots become white and bigger and move awway from it!I also asked it to fix the size of the link on the text that was very big \n\n// Step 3\n//Last step was to ask it for another fun feature and it made a BOO! button that gets activated when pressing the space button on the keyboard, when in party mood!.It creates an expanding ring, shakes the screen and blasts the dots away from the ghost.\n\n // It added new variablede and a keyPressed() funcrion to trigger the effect and send the dots away. I feel that it was really cool idea and it feels like the ghost actually scares the dots! And really intresting to see how its done \n\n\nconst COLORS = [\n  '#ff6900', '#b14622', '#d94700', '#a90000', '#5e0505',\n  '#641a70', '#87ba41', '#ffe2b8', '#ffaf24',\n];\n \nconst NUM_PARTICLES = 100;\nconst CANVAS_WIDTH = 600;\nconst CANVAS_HEIGHT = 800;\nconst GHOST_WIDTH = 200;\n \n//step2\nconst MOUSE_RANGE = 200; //dots closer than this (in pixels) to the mouse are pushed away\nconst PUSH_SPEED = 50;   // how many pixels per frame they are pushed (the most when they are right next to the mouse)\n \n \n//step3\nconst BOO_FRAMES = 30; // how long the BOO! effect lasts (in frames)\n \nlet particles = [];\nlet boo = 0;  // step3: frames left of the BOO! effect, 0 = off\nlet booX = 0; // step3: where the ghost was when you pressed space\nlet booY = 0;\nlet rave = false; // false = start screen, true = party mode\nlet img;\n \nasync function setup() {\n  img = await loadImage('ghost.png');\n  createCanvas(CANVAS_WIDTH, CANVAS_HEIGHT);\n  textAlign(CENTER, CENTER);\n  imageMode(CENTER); // draw the image from its center\n \n  for (let i = 0; i < NUM_PARTICLES; i++) {\n    particles.push({\n      x: random(width),\n      y: random(height),\n      size: random(10, 40),\n      speedX: random(-2, 2),\n      speedY: random(-2, 2),\n      color: random(COLORS),\n      scared: false, // step2: true when the ghost is pushing the dot away\n    });\n  }\n}\n \nfunction draw() {\n  background(0);\n \n  push(); // step3: everything inside push/pop can be shaken without moving the background\n  if (boo > 0) translate(random(-6, 6), random(-6, 6)); // step3: screen shake while BOO! is on\n  drawParticles();\n  drawGhost();\n  drawText();\n  drawBoo();\n  pop();\n}\n \n// ---------- Particles ----------\n \nfunction drawParticles() {\n  noStroke();\n  for (const p of particles) {\n    updateParticle(p);\n    fill(p.scared ? '#ffffff' : p.color);// step2: scared dots turn white\n    circle(p.x, p.y, p.scared ? p.size * 1.8 : p.size);  // step2: and get bigger\n  }\n}\n \nfunction updateParticle(p) {\n  // Party mode: fast, jittery movement. Start screen: slow drift.\n  const speedX = rave ? p.speedX * random(1, 3) : p.speedX * 0.5;\n  const speedY = rave ? p.speedY * random(1, 3) : p.speedY * 0.5;\n  p.x += speedX;\n  p.y += speedY;\n \n//step2\n// In party mode, dots near the mouse (the ghost) get scared and are pushed away. They turn white and become bigger.\n  \n  p.scared = false; \n  if (rave) {\n    const d = dist(p.x, p.y, mouseX, mouseY);\n    if (d > 0 && d < MOUSE_RANGE) {\n      const pushAmount = (1 - d / MOUSE_RANGE) * PUSH_SPEED; // close = strong push, far = weak push\n      p.x -= (mouseX - p.x) / d * pushAmount; // step2: minus = away from the mouse (plus pulled it in before)\n      p.y -= (mouseY - p.y) / d * pushAmount;\n      p.x = constrain(p.x, 0, width);   // step2: keep the dots inside the poster\n      p.y = constrain(p.y, 0, height);\n      p.scared = true;                  // step2: drawParticles uses this to change the look\n    }\n  }\n \n  // Bounce off the edges\n  if (p.x < 0 || p.x > width) p.speedX *= -1;\n  if (p.y < 0 || p.y > height) p.speedY *= -1;\n}\n \n// ---------- Ghost ----------\n \n// The ghost follows the mouse, only in party mode\nfunction drawGhost() {\n  if (!rave) return;\n  image(img, mouseX, mouseY, GHOST_WIDTH, GHOST_WIDTH * img.height / img.width);\n}\n \n// ---------- Text ----------\n \n// Draws one centered line of text with the given color and size\nfunction label(content, y, col, size) {\n  fill(col);\n  textSize(size);\n  text(content, width / 2, y);\n}\n \nfunction drawText() {\n  noStroke();\n  textStyle(BOLD);\n \n  if (rave) {\n    drawPartyText();\n  } else {\n    drawStartText();\n  }\n}\n \nfunction drawStartText() {\n  label('Vågar du...', 200, '#87ba41', 65);\n  label('TRYCKAAA.? 👀', 280, '#ff6900', 75);\n \n  drawArrow();\n \n  // Clickable pumpkin that starts party mode\n  label('🎃', 520, '#ffe2b8', 110);\n}\n \nfunction drawArrow() {\n  // Shaft\n  stroke('#ffe2b8');\n  strokeWeight(8);\n  line(300, 350, 300, 410);\n \n  // Head\n  fill('#ffe2b8');\n  triangle(280, 400, 320, 400, 300, 435);\n}\n \nfunction drawPartyText() {\n  label('BOOOO..SPÖKNATT', 100, random(COLORS), 56); // title flickers between colors\n  label('ÄR DU REDOO..??', 200, '#641a70', 50);\n  label('på Södertorn Högskolan', 450, '#ff6900', 40);\n  // step2: the link was pasted as markdown so it was huge, now it is normal text on two lines\n  label('Säkra den plats nu på', 685, '#ff6900', 20);\n  label('www.sh.halloween.billjeter.se! Vi ses!', 715, '#ff6900', 20);\n  label('by Emili', 770, random(COLORS), 30);\n}\n \n// ---------- BOO! ----------\n \n//step3\n// A ring flies out from where the ghost was and a big BOO! fades away\nfunction drawBoo() {\n  if (boo <= 0) return;\n \n  const progress = 1 - boo / BOO_FRAMES; // goes from 0 (start) to 1 (end)\n  const fade = 255 * (1 - progress);     // goes from 255 (visible) to 0 (gone)\n \n  // The ring gets bigger and thinner\n  noFill();\n  stroke(255, fade);\n  strokeWeight(2 + 10 * (1 - progress));\n  circle(booX, booY, progress * 900);\n \n  noStroke();\n  label('BOO!', 400, color(255, 255, 255, fade), 150);\n \n  boo--;\n}\n \n// ---------- Interaction ----------\n \n//step3\n// SPACE = BOO! (only in party mode). Every dot gets blasted away from the ghost\nfunction keyPressed() {\n  if (rave && key === ' ') {\n    boo = BOO_FRAMES;\n    booX = mouseX;\n    booY = mouseY;\n\n\n \n    for (const p of particles) {\n      const angle = atan2(p.y - booY, p.x - booX); // direction from the ghost to the dot\n      const power = random(4, 8);\n      p.speedX = cos(angle) * power;\n      p.speedY = sin(angle) * power;\n    }\n    return false; // so the page doesnt scroll when you press space\n  }\n}\n \n// Toggle party mode and reshuffle every particle's speed and color\nfunction mousePressed() {\n  rave = !rave;\n  boo = 0; // step3: stop the BOO! effect if it is still running\n \n  for (const p of particles) {\n    p.speedX = random(-8, 8);\n    p.speedY = random(-8, 8);\n    p.color = random(COLORS);\n  }\n}\n ", "assets": {"ghost.png": {"mime": "image/webp", "b64": ""}}});
